  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {"AWS": "arn:aws:iam::INGEST_ACCT_ID:role/TenantAppRole"},
      "Action": "s3:PutObject",
      "Resource": "arn:aws:s3:::telemetry-bucket/tenants/${aws:PrincipalTag/tenantId}/*",
      "Condition": {"StringEquals": {"s3:x-amz-server-side-encryption": "aws:kms"}}
    }
  ]
}
```

